  "破軍|命宮": {"줄": [{"밝기": null,"갈래": "사건","글": "돈과 벼슬자리를 함께 갖춰요. 옛 책은 이 자리를 「재관격(財官格)」 — 재물과 벼슬을 함께 갖춘 짜임 — 이라고 적었어요.","규칙": ["K2M-1093","K2M-1094"]},{"밝기": null,"갈래": "특성","글": "옛 책은 복이 두텁다(福厚)고 적었어요. 누리는 것이 많다는 말이에요.","규칙": ["K2M-1088","K2M-1095"]},{"밝기": null,"갈래": "사건","글": "살림이 쪼들려요. 옛 책은 「곤궁하다(困)」고 적었어요.","규칙": ["K2M-1089"]},{"밝기": null,"갈래": "사건","글": "이룬 것이 오래가지 않아요. 옛 책은 「오래가지 못한다(不耐久)」고 적었어요.","규칙": ["K2M-1091"]},{"밝기": "陷","갈래": "사건","글": "옛 책 『자미두수전서』는 아주 어릴 때(첫 운이 시작되기 전)에 탈이 많고 키우기 어려우며, 「부모를 형극한다(刑克父母)」고 적었어요. 부모와 일찍 헤어지거나 부모에게 해가 가는 일이에요.","규칙": ["K3-소아-흉"]}]},
  "紫微|兄弟": {"줄": [{"밝기": null,"갈래": "특성","글": "기댈 만한 손위 형제가 있어요.","규칙": ["K2-0001"]},{"밝기": null,"갈래": "사건","글": "옛 책 『자미두수전서』는 「형제를 극해 해친다(克害)」고 적었어요. 형제를 잃거나 형제에게 해가 가는 일이고, 있어도 사이가 좋지 않다고 했어요.","규칙": ["K2-0005"]},{"밝기": null,"갈래": "특성","글": "형제와 사이가 좋지 않아요. 옛 책은 「화목이 모자란다(欠和)」고 적었어요.","규칙": ["K2-0005"]}]},
  "天機|兄弟": {"줄": [{"밝기": "落陷","갈래": "특성","글": "형제와 서로 등지고 한마음이 되지 않아요.","규칙": ["K2-0008"]},{"밝기": null,"갈래": "사건","글": "옛 책 『자미두수전서』는 「형제가 있어도 극해 해친다(雖有而克害)」고 적었어요. 형제를 잃거나 형제에게 해가 가는 일이에요.","규칙": ["K2-0011"]}]},
  "太陽|兄弟": {"줄": [{"밝기": "落陷","갈래": "특성","글": "형제와 사이가 좋지 않고, 서로 힘이 되어 주지 못해요.","규칙": ["K2-0015"]},{"밝기": "落陷","갈래": "사건","글": "옛 책 『자미두수전서』는 「더 극하고 반으로 준다(更克減半)」고 적었어요. 형제를 잃는 일이 더 심해지고 형제 수가 반으로 준다는 말이에요.","규칙": ["K2-0016"]}]},
  "武曲|兄弟": {"줄": [{"밝기": null,"갈래": "특성","글": "형제와 사이가 좋지 않아요. 옛 책은 「불화목(不和睦)」이라고 적었어요.","규칙": ["K2-0020"]},{"밝기": null,"갈래": "사건","글": "옛 책 『자미두수전서』는 「외롭다(孤單)」고 적었어요. 형제가 없거나, 있어도 혼자인 것과 같다는 말이에요.","규칙": ["K2-0022"]}]},
  "天同|兄弟": {"줄": [{"밝기": "落陷","갈래": "사건","글": "형제가 적고, 따로 사는 것이 맞아요. 옛 책은 「적고 따로 살아야 하며 화목하지 않다(少宜分居不和)」고 적었어요.","규칙": ["K2-0028"]},{"밝기": "落陷","갈래": "특성","글": "형제와 사이가 좋지 않아요.","규칙": ["K2-0028"]}]},
  "廉貞|兄弟": {"줄": [{"밝기": null,"갈래": "특성","글": "형제에게 원망을 사요. 옛 책은 「초원(招怨)」이라고 적었어요.","규칙": ["K2-0030"]},{"밝기": null,"갈래": "사건","글": "옛 책 『자미두수전서』는 「극함이 있고 화목하지 않다(有克且不和)」고 적었어요. 형제를 잃거나 형제에게 해가 가고, 사이도 좋지 않은 일이에요.","규칙": ["K2-0034"]},{"밝기": null,"갈래": "특성","글": "형제와 사이가 좋지 않아요.","규칙": ["K2-0034"]}]},
